"""MCP discovers project vocabularies and follows the same transition and inbox ownership rules."""
mw_project=tool('projects_create',{'name':'Circuit MCP '+marker,'key':'W'+marker})
mw_pid=mw_project['id']
mw=tool('project_workflow_get',{'project_id':mw_pid},key=read_key)
mw=tool('project_workflow_save',{'project_id':mw_pid,'version':mw['version'],'action':'add_item','kind':'status','label':'À recetter MCP','category':'review','icon':'target','color':'#0891b2','position':25})
mw_status=next(key for key in mw['items']['status'] if key.startswith('s_'))
mw=tool('project_workflow_save',{'project_id':mw_pid,'version':mw['version'],'action':'add_item','kind':'type','label':'Incident MCP','category':'bug','icon':'bug','color':'#dc2626','position':5})
mw_type=next(key for key in mw['items']['type'] if key.startswith('t_'))
mw=tool('project_workflow_save',{'project_id':mw_pid,'version':mw['version'],'action':'transitions','restricted':True,'edges':[{'from':'todo','to':mw_status},{'from':mw_status,'to':'done'}]})
tool('project_workflow_save',{'project_id':mw_pid,'version':0,'action':'transitions'},success=False)
mw_ticket=tool('tickets_create',{'project_id':mw_pid,'fields':{'title':'Vocabulaire MCP personnalisé','type':mw_type}})
tool('tickets_update',{'id':mw_ticket['id'],'version':mw_ticket['version'],'fields':{'status':'done'}},success=False)
mw_ticket=tool('tickets_update',{'id':mw_ticket['id'],'version':mw_ticket['version'],'fields':{'status':mw_status}})
check(mw_ticket['status_label']=='À recetter MCP' and mw_ticket['type_label']=='Incident MCP','MCP hydrates custom status and type labels')
check(tool('tickets_list',{'project_id':mw_pid,'filters':{'status':mw_status,'type':mw_type}})['total']==1,'MCP filters accept project-specific keys')
check(tool('tickets_follow',{'id':mw_ticket['id'],'follow':True})['following'],'MCP can subscribe current user to ticket')
check(not tool('tickets_follow',{'id':mw_ticket['id'],'follow':False})['following'],'MCP can unsubscribe current user')
mw_form=tool('forms_save',{'project_id':mw_pid,'title':'Demande externe MCP','ticket_type':mw_type,'fields':['title']})
mw_public=mw_form['public_url'].replace(BASE,'')
_,mw_public_page,_=call(mw_public)
check(call(mw_public,{'_csrf':token(mw_public_page),'email':'mcp.external@example.net','title':'Notification personnelle MCP'})[0]==200,'public form accepts a custom project type')
mw_inbox=tool('notifications_list',{'unread_only':True})
mw_notice=next(row for row in mw_inbox['rows'] if row['title']=='Notification personnelle MCP')
check(tool('notifications_mark',{'id':mw_notice['id'],'read':True})['read'],'MCP marks own notification read')
check(not tool('notifications_mark',{'id':mw_notice['id'],'read':False})['read'],'MCP can restore unread state')
_,mw_denied=rpc('tools/call',{'name':'project_workflow_save','arguments':{'project_id':mw_pid,'version':mw['version'],'action':'transitions'}},read_key)
check('error' in mw_denied,'read token cannot change a project workflow')
